import argparse
from pathlib import Path

import yaml

from wheelleg.config import load_policy, load_robot, missing_parameters
from wheelleg.observation import OBS_DIM, OBS_FIELDS


def generate_header(robot_path: Path, policy_path: Path, *, interface_only: bool = False) -> str:
    robot, policy = load_robot(robot_path), load_policy(policy_path)
    missing = missing_parameters(robot, policy)
    if missing and not interface_only:
        raise ValueError("Cannot export a deployable configuration; missing:\n- " + "\n- ".join(missing))
    lines = [
        "// Generated by tools/gen_c_config.py; do not edit.",
        "#pragma once",
        f"#define WL_CONTROL_HZ {robot.control_hz}u",
        f"#define WL_POLICY_HZ {robot.policy_hz}u",
        f"#define WL_POLICY_DECIMATION {robot.decimation}u",
        f"#define WL_OBS_VERSION {policy.obs_version}u",
        f"#define WL_OBS_DIM {OBS_DIM}u",
        "#define WL_ACTION_DIM 6u",
        f"#define WL_DEPLOYMENT_CONFIG_READY {int(not interface_only)}",
        f"#define WL_WHEEL_REDUCTION_RATIO {float(robot.wheel_reduction_ratio)!r}f",
    ]
    offset = 0
    lines.append("// Raw physical limits: clip, scale, then replace non-finite values with zero.")
    for name, (lo, hi) in robot.observation_clip:
        lines.append(f"#define WL_OBS_CLIP_{name.upper()}_MIN {float(lo)!r}f")
        lines.append(f"#define WL_OBS_CLIP_{name.upper()}_MAX {float(hi)!r}f")
    for name, width in OBS_FIELDS:
        lines.append(f"#define WL_OBS_{name.upper()}_OFFSET {offset}u")
        offset += width
    for name, indices in (
        ("kWheelLegLegIndices", robot.leg_indices),
        ("kWheelLegWheelIndices", robot.wheel_indices),
        ("kWheelLegCanBus", robot.can_bus),
    ):
        values = ", ".join(f"{index}u" for index in indices)
        lines.append(f"static const unsigned int {name}[{len(indices)}] = {{{values}}};")
    if not interface_only:
        arrays = {
            "kWheelLegCommandScale": policy.command_scale,
            "kWheelLegDefaultQ": robot.q_default_rad,
            "kWheelLegZeroOffset": robot.q_zero_offset_rad,
            "kWheelLegMotorDirection": robot.motor_direction,
            "kWheelLegActionScale": policy.action_scales,
            "kWheelLegKp": policy.kp,
            "kWheelLegKd": policy.kd,
            "kWheelLegTorqueLimit": policy.torque_limit_nm,
        }
        for name, values in arrays.items():
            text = ", ".join(f"{float(value)!r}f" for value in values)
            lines.append(f"static const float {name}[{len(values)}] = {{{text}}};")
        data = yaml.safe_load(robot_path.read_text(encoding="utf-8"))
        if "training" in data:
            training = data["training"]
            bounds = (training["joint_lower_rad"], training["joint_upper_rad"])
            ready = all(value is not None for bound in bounds for value in bound)
            ready = ready and training["wheel_speed_limit_rad_s"] is not None
            lines.append(f"#define WL_TARGET_LIMITS_READY {int(ready)}")
            if ready:
                for name, values in zip(("kWheelLegTargetMin", "kWheelLegTargetMax"), bounds, strict=True):
                    values = list(values)
                    sign = 1 if name == "kWheelLegTargetMin" else -1
                    for i in robot.leg_indices:
                        values[i] += sign * training["joint_target_margin_rad"]
                    text = ", ".join(f"{float(value)!r}f" for value in values)
                    lines.append(f"static const float {name}[6] = {{{text}}};")
                lines.append(f"#define WL_WHEEL_SPEED_LIMIT {float(training['wheel_speed_limit_rad_s'])!r}f")
        lines.append(f"#define WL_ACTION_CLIP_ENABLED {int(policy.action_clip is not None)}")
        if policy.action_clip is not None:
            lines.append(f"#define WL_ACTION_CLIP {float(policy.action_clip)!r}f")
        for name, scale in (
            ("HEIGHT", policy.height_scale),
            ("ANGULAR_VELOCITY", policy.angular_velocity_scale),
            ("GRAVITY", policy.gravity_scale),
            ("JOINT_POSITION", policy.joint_position_scale),
            ("JOINT_VELOCITY", policy.joint_velocity_scale),
        ):
            lines.append(f"#define WL_OBS_{name}_SCALE {float(scale)!r}f")
    return "\n".join(lines) + "\n"


def main() -> None:
    parser = argparse.ArgumentParser(description="Export timing/observation contract and calibrated motor parameters")
    parser.add_argument("--robot", type=Path, required=True)
    parser.add_argument("--policy", type=Path, required=True)
    parser.add_argument("--output", type=Path, required=True)
    parser.add_argument(
        "--interface-only", action="store_true", help="Export an explicitly non-deployable bootstrap header"
    )
    args = parser.parse_args()
    header = generate_header(args.robot, args.policy, interface_only=args.interface_only)
    args.output.parent.mkdir(parents=True, exist_ok=True)
    args.output.write_text(header, encoding="utf-8")
    print(f"Written {args.output}; deployment configuration ready: {not args.interface_only}")


if __name__ == "__main__":
    main()
